Here's a Python function that implements exponential backoff with retries:

```python
import time
import random
import functools

def retry_with_exponential_backoff(max_retries, initial_delay=1, max_delay=30, backoff_factor=2):
    """
    Retry a callable with exponential backoff, with a docstring.

    Args:
        max_retries (int): Maximum number of retries.
        initial_delay (int): Initial delay between retries.
        max_delay (int): Maximum delay before giving up.
        backoff_factor (int): Factor for calculating the delay between retries.

    Returns:
        A function that retries a callable with exponential backoff.
    """

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            delay = initial_delay
            for attempt in range(max_retries + 1):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if attempt < max_retries:
                        print(f"Attempt {attempt + 1} failed with error: {e}. Retrying in {delay} seconds...")
                        time.sleep(delay)
                        delay *= backoff_factor
                    else:
                        print(f"All retries failed with error: {e}")
                        raise
        return wrapper
    return decorator

# Example usage:

