def deep_merge(base_dict, target_dict):
    """
    Deeply merges two nested dictionaries.

    Args:
        base_dict (dict): The base dictionary to merge into.
        target_dict (dict): The dictionary to merge from.

    Returns:
        dict: The merged dictionary.
    """
    for key, value in target_dict.items():
        if isinstance(value, dict):
            if key in base_dict and isinstance(base_dict[key], dict):
                deep_merge(base_dict[key], value)
            else:
                base_dict[key] = value
        else:
            base_dict[key] = value
    return base_dict

