```python
def group_records(records, key):
    if not isinstance(records, list) or not isinstance(key, (str, int, type(None))):
        raise ValueError("Invalid input: records must be a list and key must be a string, int, or None")

    if not records:
        raise ValueError("Invalid input: records list cannot be empty")

    return {key: [record for record in records if record[key] == key]}

# Example usage:
