Here's a Python generator function that parses a log line into a timestamp and a message:

```python
import re
from datetime import datetime

class LogParser:
    def __init__(self):
        self.timestamp_pattern = re.compile(r"^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}\.\d{3}$")

    def parse_log_line(self, line):
        match = self.timestamp_pattern.match(line)
        if match:
            timestamp = datetime.strptime(match.group(), "%Y-%m-%d %H:%M:%S.%f")
            return timestamp, line[match.end():]
        else:
            return None, None

def parse_log_lines(lines):
    parser = LogParser()
    return (parser.parse_log_line(line) for line in lines)

# Example usage:
log_lines = [
    "2022-01-01 12:00:00.123456",
    "2022-01-02 13:00:00.234567",
    "Invalid log line"
]

for timestamp, message in parse_log_lines(log_lines):
    print(f"Timestamp: {timestamp}, Message: {message}")
