def is_valid_ipv4(address):
    """
    Checks if a string is a well-formed IPv4 address.

    Args:
        address (str): The address to be validated.

    Returns:
        bool: True if the address is valid, False otherwise.
    """
    parts = address.split('.')
    if len(parts) != 4:
